using StateLandGovernance.GovernanceIntelligence.Application.RegulatoryReports;
using StateLandGovernance.GovernanceIntelligence.Application.DTOs;
namespace StateLandGovernance.UnitTests.GovernanceIntelligence;
public sealed class RegulatoryFollowupTests
{
    static RecordRegulatoryFollowup Input()=>new(Guid.NewGuid(),"RULE-1","ClarificationRequested",null,"Missing information must be clarified.","Please explain the missing information.",["Recorded source"],0);
    [Fact] public void Clarification_ValidatesBoundedTextAndNormalizes(){var x=Input();Assert.Equal(x.Remarks,RegulatoryFollowupInput.Validate(x).Remarks);Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(x with{Remarks="short"}));Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(x with{MissingInformation=null}));}
    [Theory][InlineData("NoAdditionalConcern")][InlineData("AdditionalInformationRequired")][InlineData("FurtherInstitutionalLegalReview")]
    public void HumanReview_UsesOnlyExplicitOutcomes(string outcome){var x=Input() with{Operation="HumanReviewRecorded",ReviewOutcome=outcome,MissingInformation=null};Assert.Equal(outcome,RegulatoryFollowupInput.Validate(x).ReviewOutcome);Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(x with{ReviewOutcome="Approved"}));}
    [Fact] public void References_AreBoundedAndNeverBecomeEvidenceAuthority(){var x=Input();Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(x with{References=new string[11]}));Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(x with{References=[new string('x',501)]}));Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(x with{SubmissionKey=Guid.Empty}));Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(x with{ExpectedRevision=-1}));}
    [Fact] public void OriginalFinding_ControlsPermittedOperation(){var f=new ComplianceFindingDto("RULE-1","v1","Test","Applicable","Compliant","Info",false,false,"Recorded fact","Recorded requirement","Missing","NotApplicable","Source","Document","1","Clarify");Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.ValidateFinding(Input(),f));RegulatoryFollowupInput.ValidateFinding(Input(),f with{Status="InsufficientInformation"});Assert.Equal("Compliant",f.Status);}
    [Fact] public void MigrationDown_RefusesHistoryRemoval(){var migration=new StateLandGovernance.GovernanceIntelligence.Infrastructure.Persistence.Migrations.AddRegulatoryFollowupEvents();Assert.Throws<InvalidOperationException>(()=>migration.DownOperations);}
    [Fact] public void HistoryCursor_RoundTripsExactPosition(){var cursor=new RegulatoryFollowupCursor(DateTimeOffset.UtcNow,Guid.NewGuid());Assert.Equal(cursor,RegulatoryFollowupCursor.Parse(cursor.Encode()));Assert.Null(RegulatoryFollowupCursor.Parse(null));}
    [Theory][InlineData("")][InlineData("forged")][InlineData("-1.11111111000040008000000000000001")][InlineData("123.00000000000000000000000000000000")]
    public void HistoryCursor_RejectsMalformedPositions(string value)=>Assert.Throws<ArgumentException>(()=>RegulatoryFollowupCursor.Parse(value));
    static RecordRegulatoryFollowup NoFollowup()=>Input() with{Operation="NoFollowupRequired",MissingInformation=null};
    static ComplianceFindingDto SavedFinding()=>new("RULE-1","v1","Test","Applicable","Compliant","Info",false,false,"Recorded fact","Recorded requirement","Provided","NotApplicable","Source","Document","1","No additional action.");
    [Fact] public void NoFollowup_RequiresRationaleAndNoOtherPayload(){var input=NoFollowup();var normalized=RegulatoryFollowupInput.Validate(input);Assert.Equal(input.Operation,normalized.Operation);Assert.Equal(input.Remarks,normalized.Remarks);Assert.Equal(input.References,normalized.References);Assert.Null(normalized.ReviewOutcome);Assert.Null(normalized.MissingInformation);foreach(var remarks in new[]{"", "short",new string('x',2001)})Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(input with{Remarks=remarks}));Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(input with{ReviewOutcome="NoAdditionalConcern"}));Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(input with{MissingInformation=""}));}
    [Theory][InlineData("InsufficientInformation")][InlineData("RequiresHumanReview")][InlineData("RequiresReview")][InlineData("Conditional")][InlineData("NonCompliant")][InlineData("Unknown")]
    public void NoFollowup_CannotWaiveSavedReviewOrUnresolvedOutcome(string status)=>Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.ValidateFinding(NoFollowup(),SavedFinding() with{Status=status}));
    [Fact] public void NoFollowup_RespectsMandatoryFlagsEvenOnCompliantStatus(){foreach(var f in new[]{SavedFinding() with{RequiresHumanReview=true},SavedFinding() with{IsBlocking=true}})Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.ValidateFinding(NoFollowup(),f));}
    [Fact] public void NoFollowup_EligibleSavedFinding_RemainsUnchanged(){var f=SavedFinding();var before=RegulatoryFollowupInput.FindingHash(f);RegulatoryFollowupInput.ValidateFinding(NoFollowup(),f);Assert.Equal(before,RegulatoryFollowupInput.FindingHash(f));Assert.Equal("Compliant",f.Status);}
    [Fact] public void NoFollowupMigrationDown_RefusesHistoryRemoval(){var migration=new StateLandGovernance.GovernanceIntelligence.Infrastructure.Persistence.Migrations.AllowRegulatoryNoFollowupRequired();Assert.Throws<InvalidOperationException>(()=>migration.DownOperations);}
}
